public class PoolDemo {
    public static void main(String[] args) {
        String a = "java";
        String b = "java";
        String c = new String("java");
        String d = c.intern();
        String part = "ja";
        String e = part + "va";
        String f = "ja" + "va";
        System.out.println("a == b          : " + (a == b));
        System.out.println("a == c          : " + (a == c));
        System.out.println("a.equals(c)     : " + a.equals(c));
        System.out.println("a == d (intern) : " + (a == d));
        System.out.println("a == e (runtime): " + (a == e));
        System.out.println("a == f (const)  : " + (a == f));
    }
}

