public class Methods {
    public static void main(String[] args) {
        String s = "\u2003 Hello, Java  \n";       // starts with an EM SPACE
        System.out.println(s.trim().length() + " " + s.strip().length());
        System.out.println(" ".isBlank() + " " + "".isEmpty());
