        System.out.println("a,b,,c,,".split(",", -1).length);
        System.out.println(Arrays.toString("a1b22c".split("\\d+")));
        System.out.println(Arrays.toString("".split(",")) + " " + "".split(",").length);
        System.out.println(Arrays.toString("a.b".split(".")));
