        System.out.println(r);
    }
}

public class SwitchOnString {
    static int level(String day) {
        return switch (day) {
            case "MON", "TUE" -> 1;
            case "WED"        -> 2;
            default           -> 0;
        };
    }
    public static void main(String[] args) {
        System.out.println(level("TUE") + " " + level("WED") + " " + level("tue"));
    }
}

import java.util.Arrays;
import java.util.Comparator;
import java.util.Map;
import java.util.StringJoiner;
import java.util.TreeMap;
import java.util.function.Function;
import java.util.stream.Collectors;

public class Wf {
    public static void main(String[] args) {
        String text = """
            To be, or not to be, that is the question:
            Whether 'tis nobler in the mind to suffer
            """;
        Map<String, Long> freq = Arrays.stream(text.toLowerCase().split("\\W+"))
            .filter(w -> !w.isBlank())
            .collect(Collectors.groupingBy(Function.identity(), TreeMap::new,
                Collectors.counting()));
        System.out.println(freq);
        String top = freq.entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue().reversed()
                .thenComparing(Map.Entry.comparingByKey()))
            .limit(3)
            .map(e -> e.getKey() + "=" + e.getValue())
            .collect(Collectors.joining(", ", "[", "]"));
        System.out.println(top);

        StringJoiner sj = new StringJoiner(", ", "{", "}");
        sj.setEmptyValue("EMPTY");
        System.out.println(sj);
        sj.add("a").add("b");
        System.out.println(sj + " " + String.join("|", "x", "y", "z"));

        System.out.println("hello".chars().filter(c -> c == 'l').count());
        System.out.println("hello".chars().mapToObj(c -> String.valueOf((char) c))
            .collect(Collectors.joining("-")));
        System.out.println(new StringBuilder("racecar").reverse().toString().equals("racecar"));

        // hash caching
        String k = "Aa";
        String k2 = "BB";
        System.out.println(k.hashCode() + " " + k2.hashCode() + " " + k.equals(k2));
        char[] pw = {'s', '3', 'c'};
        Arrays.fill(pw, '\0');
        System.out.println((int) pw[0]);
        System.out.println("a,b,,c,,".split(",").length + " " + "a,b,,c,,".split(",", -1).length
            + " " + Arrays.toString(" x  y ".split(" ")));
    }
}
